-- Migration 035 — Reglas de lista según la planilla CORREGIDA por Mati (08/09/2026).
-- GENERADO por scripts/gen-listas-seed-v2.mjs. NO editar a mano: corregir el script y regenerar.
--
-- Reemplaza la carga de las migraciones 021/022/025, que traducía mal la notación de la
-- planilla. Los tres errores que corrige, detectados en la auditoría del 08/09:
--   1. "10+1" se había leído como la promo general de 10 bultos surtidos. Es una
--      bonificación: se carga como 11 unidades en la lista 2.
--   2. "BOLSA" se había leído como "20 kg", que dejaba afuera las bolsas de 25 y 30 kg.
--   3. "BOLS +10%" y "BOLSA" habían quedado con la MISMA condición, así que la lista 2
--      era inalcanzable y todo pedido disparaba "le estás cobrando de más" (110 casos).

alter table listas_reglas add column if not exists opcional boolean not null default false;
alter table listas_reglas add column if not exists bonificacion text;
comment on column listas_reglas.opcional is 'La condición habilita la lista pero no le da derecho al cliente (celda "BOLS +10%").';
comment on column listas_reglas.bonificacion is 'La promo como la escribe la planilla ("10+1"): el umbral ya viene sumado.';
alter table listas_reglas drop constraint if exists listas_reglas_condicion_check;
alter table listas_reglas add constraint listas_reglas_condicion_check
  check (condicion in ('libre','promo_general','min','max','excluido','bulto_cerrado'));

-- Las exclusiones no salen de la planilla: se preservan aparte (ver abajo).
delete from listas_reglas where tenant_id = '00000000-0000-0000-0000-000000000001' and condicion <> 'excluido';

